BEGIN;
CREATE SCHEMA driver_portal_private;
REVOKE ALL ON SCHEMA driver_portal_private FROM PUBLIC; GRANT USAGE ON SCHEMA driver_portal_private TO anon,authenticated,service_role;
CREATE TABLE driver_portal_private.config(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),key_hash text NOT NULL CHECK(key_hash~'^[0-9a-f]{64}$'));
CREATE TABLE driver_portal_private.invites(company_id uuid PRIMARY KEY REFERENCES public.companies(id),token text UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true,updated_by uuid NOT NULL REFERENCES auth.users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE driver_portal_private.challenges(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES public.companies(id),driver_id uuid NOT NULL REFERENCES public.motoristas(id) ON DELETE CASCADE,invite_token text NOT NULL,code_hash text NOT NULL,ip_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '5 minutes',attempts integer NOT NULL DEFAULT 0,used_at timestamptz,status text NOT NULL DEFAULT 'sending' CHECK(status IN ('sending','accepted','failed','unknown')));
CREATE INDEX portal_challenges_driver ON driver_portal_private.challenges(company_id,driver_id,created_at DESC); CREATE INDEX portal_challenges_ip ON driver_portal_private.challenges(ip_hash,created_at DESC);
CREATE TABLE driver_portal_private.sessions(token_hash text PRIMARY KEY,company_id uuid NOT NULL REFERENCES public.companies(id),driver_id uuid NOT NULL REFERENCES public.motoristas(id) ON DELETE CASCADE,invite_token text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '12 hours');
CREATE INDEX portal_sessions_driver ON driver_portal_private.sessions(driver_id);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['config','invites','challenges','sessions'] LOOP EXECUTE format('ALTER TABLE driver_portal_private.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON driver_portal_private.%I FROM PUBLIC,anon,authenticated',t); EXECUTE format('CREATE POLICY server_only ON driver_portal_private.%I TO anon,authenticated USING(false) WITH CHECK(false)',t);END LOOP;END $$;
CREATE TABLE public.maintenance_driver_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),request_id uuid NOT NULL,protocol text GENERATED ALWAYS AS ('SM-'||upper(substr(replace(id::text,'-',''),1,12))) STORED UNIQUE,driver_id uuid REFERENCES public.motoristas(id) ON DELETE SET NULL,vehicle_id uuid REFERENCES public.veiculos(id) ON DELETE SET NULL,driver_name text NOT NULL,vehicle_plate text NOT NULL,km integer NOT NULL CHECK(km BETWEEN 0 AND 10000000),defects text NOT NULL CHECK(length(btrim(defects)) BETWEEN 5 AND 10000),severity text NOT NULL CHECK(severity IN ('leve','media','urgente')),status text NOT NULL DEFAULT 'nova' CHECK(status IN ('nova','analise','pendente','resolvida','cancelada')),feedback text NOT NULL DEFAULT '',version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),resolved_at timestamptz,updated_by uuid REFERENCES auth.users(id),vehicle_snapshot jsonb NOT NULL,partner_types text[] NOT NULL DEFAULT '{}',ack_status text NOT NULL DEFAULT 'pending' CHECK(ack_status IN ('pending','sending','accepted','failed','unknown','unavailable')),ack_token uuid,ack_started_at timestamptz,ack_message_id text,UNIQUE(company_id,request_id),UNIQUE(id,company_id));
CREATE INDEX driver_reports_company_status ON public.maintenance_driver_reports(company_id,status,created_at DESC,id);
CREATE INDEX driver_reports_driver ON public.maintenance_driver_reports(driver_id,created_at DESC);CREATE INDEX driver_reports_vehicle ON public.maintenance_driver_reports(vehicle_id);CREATE INDEX driver_reports_actor ON public.maintenance_driver_reports(updated_by);
CREATE TABLE public.maintenance_driver_report_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),report_id uuid NOT NULL,actor_id uuid REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),action text NOT NULL,message text NOT NULL,FOREIGN KEY(report_id,company_id) REFERENCES public.maintenance_driver_reports(id,company_id));
CREATE INDEX driver_report_events_report ON public.maintenance_driver_report_events(company_id,report_id,created_at);CREATE INDEX driver_report_events_actor ON public.maintenance_driver_report_events(actor_id);
CREATE TABLE public.maintenance_driver_report_dispatches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),report_id uuid NOT NULL,partner_id uuid NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','accepted','failed','unknown','unavailable','obsolete')),claim_token uuid,started_at timestamptz,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),attempts integer NOT NULL DEFAULT 0,message_id text,error_message text,UNIQUE(report_id,partner_id),FOREIGN KEY(report_id,company_id) REFERENCES public.maintenance_driver_reports(id,company_id),FOREIGN KEY(partner_id,company_id) REFERENCES public.maintenance_partners(id,company_id));
CREATE INDEX driver_report_dispatch_company ON public.maintenance_driver_report_dispatches(company_id,report_id);CREATE INDEX driver_report_dispatch_partner ON public.maintenance_driver_report_dispatches(company_id,partner_id);
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['maintenance_driver_reports','maintenance_driver_report_events','maintenance_driver_report_dispatches'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);EXECUTE format('GRANT SELECT ON public.%I TO authenticated',t);EXECUTE format('GRANT ALL ON public.%I TO service_role',t);EXECUTE format('CREATE POLICY company_read ON public.%I FOR SELECT TO authenticated USING(maintenance_private.partner_access(company_id))',t);END LOOP;END $$;
CREATE FUNCTION driver_portal_private.hash(value text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT encode(sha256(convert_to(value,'UTF8')),'hex'); $$;
REVOKE ALL ON FUNCTION driver_portal_private.hash(text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION driver_portal_private.phone(value text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$ DECLARE raw text:=regexp_replace(coalesce(value,''),'[^0-9]','','g');BEGIN IF coalesce(value,'') LIKE '+%' AND raw NOT LIKE '55%' THEN RETURN NULL;END IF;IF length(raw) IN (10,11) THEN raw:='55'||raw;END IF;IF raw !~ '^55[1-9][0-9][2-9][0-9]{7,8}$' THEN RETURN NULL;END IF;RETURN raw;END $$;
REVOKE ALL ON FUNCTION driver_portal_private.phone(text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION driver_portal_private.report_public(r public.maintenance_driver_reports) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$ SELECT jsonb_build_object('id',r.id,'protocol',r.protocol,'driver_name',r.driver_name,'vehicle_plate',r.vehicle_plate,'km',r.km,'defects',r.defects,'severity',r.severity,'status',r.status,'feedback',r.feedback,'created_at',r.created_at,'updated_at',r.updated_at,'ack_status',r.ack_status);$$;
REVOKE ALL ON FUNCTION driver_portal_private.report_public(public.maintenance_driver_reports) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION driver_portal_private.gateway(server_key text,action text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE inv driver_portal_private.invites;ch driver_portal_private.challenges;s driver_portal_private.sessions;d public.motoristas;v public.veiculos;r public.maintenance_driver_reports;phone text;created boolean:=false;
BEGIN
IF length(coalesce(server_key,''))<32 OR NOT EXISTS(SELECT 1 FROM driver_portal_private.config WHERE key_hash=driver_portal_private.hash(server_key)) THEN RAISE EXCEPTION 'Acesso não autorizado.' USING ERRCODE='42501';END IF;
SELECT i.* INTO inv FROM driver_portal_private.invites i JOIN public.companies c ON c.id=i.company_id AND c.ativo WHERE i.token=b->>'invite' AND i.active FOR UPDATE OF i;
IF NOT FOUND THEN RAISE EXCEPTION 'Link inválido ou desativado. Solicite o link à equipe.' USING ERRCODE='42501';END IF;
IF action='info' THEN RETURN jsonb_build_object('company',(SELECT nome FROM public.companies WHERE id=inv.company_id),'drivers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'nome',nome) ORDER BY nome,id) FROM public.motoristas WHERE company_id=inv.company_id AND coalesce(lower(status),'') NOT IN ('inativo','desligado','excluido','excluído','bloqueado')),'[]'::jsonb));END IF;
IF action='request_code' THEN
SELECT * INTO ch FROM driver_portal_private.challenges WHERE id=(b->>'request_id')::uuid;
IF FOUND THEN IF ch.company_id<>inv.company_id OR ch.invite_token<>inv.token OR ch.driver_id<>(b->>'driver_id')::uuid THEN RAISE EXCEPTION 'Solicitação inválida.' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('status',ch.status,'challenge_id',ch.id);END IF;
SELECT * INTO d FROM public.motoristas WHERE id=(b->>'driver_id')::uuid AND company_id=inv.company_id AND coalesce(lower(status),'') NOT IN ('inativo','desligado','excluido','excluído','bloqueado') FOR SHARE;
IF NOT FOUND THEN RAISE EXCEPTION 'Motorista não disponível nesta empresa.';END IF;
phone:=driver_portal_private.phone(d.telefone);IF phone IS NULL THEN RAISE EXCEPTION 'Seu WhatsApp não está válido no cadastro. Peça à equipe para atualizar seu contato.';END IF;
IF EXISTS(SELECT 1 FROM driver_portal_private.challenges WHERE driver_id=d.id AND created_at>clock_timestamp()-interval '60 seconds') OR (SELECT count(*) FROM driver_portal_private.challenges WHERE driver_id=d.id AND created_at>clock_timestamp()-interval '1 hour')>=5 OR (SELECT count(*) FROM driver_portal_private.challenges WHERE ip_hash=b->>'ip_hash' AND created_at>clock_timestamp()-interval '1 minute')>=15 OR (SELECT count(*) FROM driver_portal_private.challenges WHERE company_id=inv.company_id AND created_at>clock_timestamp()-interval '1 hour')>=600 THEN RAISE EXCEPTION 'Aguarde antes de solicitar outro código.' USING ERRCODE='P0001';END IF;
IF coalesce(b->>'code_hash','')!~'^[0-9a-f]{64}$' OR coalesce(b->>'ip_hash','')!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Solicitação inválida.';END IF;
INSERT INTO driver_portal_private.challenges(id,company_id,driver_id,invite_token,code_hash,ip_hash) VALUES((b->>'request_id')::uuid,inv.company_id,d.id,inv.token,b->>'code_hash',b->>'ip_hash') RETURNING * INTO ch;
RETURN jsonb_build_object('status','claimed','challenge_id',ch.id,'phone',phone,'name',d.nome);END IF;
IF action IN ('code_finish','verify') THEN
SELECT * INTO ch FROM driver_portal_private.challenges WHERE id=(b->>'challenge_id')::uuid AND company_id=inv.company_id AND invite_token=inv.token FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'Código não encontrado. Solicite novamente.';END IF;
IF action='code_finish' THEN IF ch.status='sending' AND b->>'status' IN ('accepted','failed','unknown') THEN UPDATE driver_portal_private.challenges SET status=b->>'status' WHERE id=ch.id;END IF;RETURN jsonb_build_object('status',b->>'status','challenge_id',ch.id);END IF;
IF ch.expires_at<clock_timestamp() OR ch.used_at IS NOT NULL OR ch.attempts>=5 OR ch.status NOT IN ('accepted','unknown','sending') THEN RETURN jsonb_build_object('error','Código expirado, já usado ou indisponível. Solicite outro.');END IF;
UPDATE driver_portal_private.challenges SET attempts=attempts+1 WHERE id=ch.id;
IF ch.code_hash IS DISTINCT FROM b->>'code_hash' THEN RETURN jsonb_build_object('error','Código incorreto. Confira o WhatsApp.');END IF;
IF coalesce(b->>'session_hash','')!~'^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Sessão inválida.';END IF;
IF NOT EXISTS(SELECT 1 FROM public.motoristas WHERE id=ch.driver_id AND company_id=inv.company_id AND coalesce(lower(status),'') NOT IN ('inativo','desligado','excluido','excluído','bloqueado')) THEN RETURN jsonb_build_object('error','Cadastro do motorista indisponível.');END IF;
UPDATE driver_portal_private.challenges SET used_at=clock_timestamp() WHERE id=ch.id;
INSERT INTO driver_portal_private.sessions(token_hash,company_id,driver_id,invite_token) VALUES(b->>'session_hash',inv.company_id,ch.driver_id,inv.token);RETURN jsonb_build_object('verified',true);END IF;
SELECT * INTO s FROM driver_portal_private.sessions WHERE token_hash=b->>'session_hash' AND company_id=inv.company_id AND invite_token=inv.token AND expires_at>clock_timestamp();
IF NOT FOUND THEN RAISE EXCEPTION 'Sua sessão expirou. Entre novamente pelo seu nome.' USING ERRCODE='42501';END IF;
SELECT * INTO d FROM public.motoristas WHERE id=s.driver_id AND company_id=inv.company_id AND coalesce(lower(status),'') NOT IN ('inativo','desligado','excluido','excluído','bloqueado');IF NOT FOUND THEN RAISE EXCEPTION 'Motorista indisponível.' USING ERRCODE='42501';END IF;
IF action='logout' THEN DELETE FROM driver_portal_private.sessions WHERE token_hash=s.token_hash;RETURN '{}'::jsonb;END IF;
IF action='home' THEN RETURN jsonb_build_object('name',d.nome,'vehicles',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'placa',placa,'marca_modelo',marca_modelo,'km_atual',km_atual) ORDER BY placa) FROM public.veiculos WHERE company_id=inv.company_id),'[]'::jsonb),'reports',coalesce((SELECT jsonb_agg(driver_portal_private.report_public(x) ORDER BY x.created_at DESC) FROM (SELECT * FROM public.maintenance_driver_reports WHERE company_id=inv.company_id AND driver_id=d.id ORDER BY created_at DESC LIMIT 100) x),'[]'::jsonb));END IF;
IF action='submit' THEN
SELECT * INTO r FROM public.maintenance_driver_reports WHERE company_id=inv.company_id AND request_id=(b->>'request_id')::uuid;IF FOUND THEN IF r.driver_id<>d.id THEN RAISE EXCEPTION 'Solicitação inválida.' USING ERRCODE='42501';END IF;RETURN driver_portal_private.report_public(r);END IF;
IF (SELECT count(*) FROM public.maintenance_driver_reports WHERE driver_id=d.id AND created_at>clock_timestamp()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'Muitas solicitações. Aguarde ou contate a equipe.';END IF;
SELECT * INTO v FROM public.veiculos WHERE id=(b->>'vehicle_id')::uuid AND company_id=inv.company_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Escolha uma placa cadastrada nesta empresa.';END IF;
IF coalesce(b->>'km','')!~'^[0-9]{1,8}$' OR (b->>'km')::integer>10000000 OR (b->>'km')::integer<coalesce(v.km_atual,0) THEN RAISE EXCEPTION 'Informe o KM atual, sem diminuir o último odômetro cadastrado.';END IF;
IF b->>'severity' NOT IN ('leve','media','urgente') OR length(btrim(coalesce(b->>'defects','')))<5 OR length(b->>'defects')>10000 THEN RAISE EXCEPTION 'Informe os defeitos e o grau da manutenção.';END IF;
INSERT INTO public.maintenance_driver_reports(company_id,request_id,driver_id,vehicle_id,driver_name,vehicle_plate,km,defects,severity,vehicle_snapshot) VALUES(inv.company_id,(b->>'request_id')::uuid,d.id,v.id,d.nome,v.placa,(b->>'km')::integer,btrim(b->>'defects'),b->>'severity',jsonb_build_object('placa',v.placa,'marca_modelo',v.marca_modelo,'ano_fabricacao',v.ano_fabricacao,'ano_modelo',v.ano_modelo,'chassi',v.chassi,'tipo',v.tipo)) RETURNING * INTO r;
UPDATE public.veiculos SET km_atual=r.km WHERE id=v.id;
INSERT INTO public.maintenance_driver_report_events(company_id,report_id,action,message) VALUES(inv.company_id,r.id,'criacao','Solicitação enviada pelo motorista verificado via WhatsApp.');
INSERT INTO public.maintenance_vehicle_events(company_id,vehicle_id,occurred_at,kind,description,snapshot,source_key) VALUES(inv.company_id,v.id,r.created_at,'ocorrencia','Solicitação do motorista: '||r.protocol,jsonb_build_object('protocol',r.protocol,'relator',d.nome,'km',r.km,'defeitos',r.defects,'gravidade',r.severity),'driver-report/'||r.id);
RETURN driver_portal_private.report_public(r);END IF;
SELECT * INTO r FROM public.maintenance_driver_reports WHERE id=(b->>'id')::uuid AND company_id=inv.company_id AND driver_id=d.id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Solicitação não encontrada.' USING ERRCODE='42501';END IF;
IF action='ack_claim' THEN
IF r.ack_status='sending' AND r.ack_started_at<clock_timestamp()-interval '2 minutes' THEN UPDATE public.maintenance_driver_reports SET ack_status='unknown' WHERE id=r.id;r.ack_status:='unknown';END IF;
IF r.ack_status='accepted' OR r.ack_status='sending' OR (coalesce((b->>'automatic')::boolean,false) AND r.ack_status<>'pending') OR (r.ack_status='unknown' AND NOT coalesce((b->>'confirm_uncertain')::boolean,false)) THEN RETURN jsonb_build_object('status',r.ack_status);END IF;
phone:=driver_portal_private.phone(d.telefone);IF phone IS NULL THEN UPDATE public.maintenance_driver_reports SET ack_status='unavailable' WHERE id=r.id;RETURN jsonb_build_object('status','unavailable');END IF;
UPDATE public.maintenance_driver_reports SET ack_status='sending',ack_started_at=clock_timestamp(),ack_token=gen_random_uuid() WHERE id=r.id RETURNING * INTO r;
RETURN jsonb_build_object('status','claimed','token',r.ack_token,'phone',phone,'text','Olá, '||d.nome||'! Obrigado por reportar os defeitos do veículo '||r.vehicle_plate||'. Recebemos sua solicitação '||r.protocol||' (prioridade: '||r.severity||'). Ela será encaminhada para análise da equipe de transporte, que avaliará o atendimento em breve. Você pode acompanhar o andamento pelo portal.');END IF;
IF action='ack_finish' THEN IF r.ack_status='sending' AND r.ack_token=(b->>'token')::uuid AND b->>'status' IN ('accepted','failed','unknown') THEN UPDATE public.maintenance_driver_reports SET ack_status=b->>'status',ack_message_id=left(b->>'message_id',200) WHERE id=r.id;INSERT INTO public.maintenance_driver_report_events(company_id,report_id,action,message) VALUES(inv.company_id,r.id,'confirmacao','Confirmação pelo WhatsApp: '||(b->>'status'));END IF;RETURN jsonb_build_object('status',(SELECT ack_status FROM public.maintenance_driver_reports WHERE id=r.id));END IF;
RAISE EXCEPTION 'Ação inválida.';
END $$;
REVOKE ALL ON FUNCTION driver_portal_private.gateway(text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION driver_portal_private.gateway(text,text,jsonb) TO anon,authenticated;
CREATE FUNCTION public.driver_maintenance_gateway(server_key text,command text,body jsonb) RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT driver_portal_private.gateway(server_key,command,body); $$;
REVOKE ALL ON FUNCTION public.driver_maintenance_gateway(text,text,jsonb) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.driver_maintenance_gateway(text,text,jsonb) TO anon,authenticated;

CREATE FUNCTION driver_portal_private.admin_command(c uuid,action text,b jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.maintenance_driver_reports;dispatch public.maintenance_driver_report_dispatches;recipient public.maintenance_partners;inv driver_portal_private.invites;page_number integer:=greatest(1,least(coalesce((b->>'page')::integer,1),100000));selected text[];amount integer;phone text;view_status text:=coalesce(b->>'status','');term text:=left(coalesce(b->>'search',''),100);
BEGIN
IF auth.uid() IS NULL OR NOT maintenance_private.partner_access(c) THEN RAISE EXCEPTION 'Acesso não autorizado à empresa.' USING ERRCODE='42501';END IF;
IF action IN ('link','rotate','revoke','status','prepare_dispatch','dispatch_claim','dispatch_finish') AND NOT maintenance_private.partner_access(c,true) THEN RAISE EXCEPTION 'Seu perfil não pode gerenciar estas solicitações.' USING ERRCODE='42501';END IF;
IF action IN ('link','rotate','revoke') THEN
IF action='revoke' THEN UPDATE driver_portal_private.invites SET active=false,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE company_id=c;RETURN jsonb_build_object('active',false);END IF;
INSERT INTO driver_portal_private.invites(company_id,token,updated_by) VALUES(c,replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-',''),auth.uid()) ON CONFLICT(company_id) DO NOTHING;
IF action='rotate' THEN UPDATE driver_portal_private.invites SET token=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-',''),active=true,updated_by=auth.uid(),updated_at=clock_timestamp() WHERE company_id=c;END IF;
SELECT * INTO inv FROM driver_portal_private.invites WHERE company_id=c;RETURN jsonb_build_object('invite',inv.token,'active',inv.active);END IF;
IF action='list' THEN RETURN jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC,x.id) FROM (SELECT id,protocol,driver_name,vehicle_plate,km,defects,severity,status,feedback,version,created_at,updated_at,ack_status FROM public.maintenance_driver_reports WHERE company_id=c AND (coalesce(b->>'severity','')='' OR severity=b->>'severity') AND (view_status='' OR status=view_status OR (view_status='atuais' AND status IN ('nova','analise','pendente'))) AND (term='' OR driver_name ILIKE '%'||term||'%' OR vehicle_plate ILIKE '%'||term||'%' OR protocol ILIKE '%'||term||'%') ORDER BY created_at DESC,id OFFSET (page_number-1)*20 LIMIT 20) x),'[]'::jsonb),'count',(SELECT count(*) FROM public.maintenance_driver_reports WHERE company_id=c AND (coalesce(b->>'severity','')='' OR severity=b->>'severity') AND (view_status='' OR status=view_status OR (view_status='atuais' AND status IN ('nova','analise','pendente'))) AND (term='' OR driver_name ILIKE '%'||term||'%' OR vehicle_plate ILIKE '%'||term||'%' OR protocol ILIKE '%'||term||'%')),'counts',jsonb_build_object('atuais',(SELECT count(*) FROM public.maintenance_driver_reports WHERE company_id=c AND status IN ('nova','analise','pendente')),'pendentes',(SELECT count(*) FROM public.maintenance_driver_reports WHERE company_id=c AND status='pendente'),'resolvidas',(SELECT count(*) FROM public.maintenance_driver_reports WHERE company_id=c AND status='resolvida'),'urgentes',(SELECT count(*) FROM public.maintenance_driver_reports WHERE company_id=c AND severity='urgente' AND status IN ('nova','analise','pendente'))));END IF;
SELECT * INTO r FROM public.maintenance_driver_reports WHERE id=(b->>'id')::uuid AND company_id=c FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Solicitação não encontrada nesta empresa.' USING ERRCODE='42501';END IF;
IF action='detail' THEN RETURN jsonb_build_object('report',to_jsonb(r)-'ack_token','events',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.created_at,e.id) FROM public.maintenance_driver_report_events e WHERE report_id=r.id AND company_id=c),'[]'::jsonb),'dispatches',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x.id,'partner',coalesce(p.nome_fantasia,p.razao_social),'status',x.status,'attempts',x.attempts,'error',x.error_message,'updated_at',x.updated_at)) FROM public.maintenance_driver_report_dispatches x JOIN public.maintenance_partners p ON p.id=x.partner_id WHERE x.report_id=r.id AND x.company_id=c),'[]'::jsonb));END IF;
IF action IN ('status','prepare_dispatch') AND r.version IS DISTINCT FROM (b->>'version')::integer THEN RAISE EXCEPTION 'Solicitação alterada. Atualize a página antes de continuar.' USING ERRCODE='40001';END IF;
IF action='status' THEN
IF b->>'status' NOT IN ('nova','analise','pendente','resolvida','cancelada') OR b->>'status' IS NULL THEN RAISE EXCEPTION 'Situação inválida.';END IF;
IF length(coalesce(b->>'feedback',''))>2000 OR (b->>'status' IN ('pendente','resolvida','cancelada') AND length(btrim(coalesce(b->>'feedback','')))<3) THEN RAISE EXCEPTION 'Informe uma resposta para o motorista (até 2000 caracteres).';END IF;
UPDATE public.maintenance_driver_reports SET status=b->>'status',feedback=btrim(coalesce(b->>'feedback','')),resolved_at=CASE WHEN b->>'status'='resolvida' THEN clock_timestamp() ELSE NULL END,version=version+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE id=r.id RETURNING * INTO r;
INSERT INTO public.maintenance_driver_report_events(company_id,report_id,actor_id,action,message) VALUES(c,r.id,auth.uid(),'situacao','Situação: '||r.status||'. '||r.feedback);RETURN to_jsonb(r)-'ack_token';END IF;
IF action='prepare_dispatch' THEN
IF r.status IN ('resolvida','cancelada') THEN RAISE EXCEPTION 'Reabra a solicitação antes de encaminhar.';END IF;
selected:=ARRAY(SELECT jsonb_array_elements_text(coalesce(b->'types','[]'::jsonb)));IF NOT maintenance_private.quote_types_valid(selected) OR cardinality(selected)=0 THEN RAISE EXCEPTION 'Selecione os tipos de oficinas. Sem seleção, nenhum envio.';END IF;
UPDATE public.maintenance_driver_reports SET partner_types=selected,status='analise',updated_at=clock_timestamp(),updated_by=auth.uid(),version=version+1 WHERE id=r.id RETURNING * INTO r;
UPDATE public.maintenance_driver_report_dispatches SET status='obsolete',error_message='Oficina fora dos filtros.' WHERE report_id=r.id AND status IN ('pending','failed','unavailable') AND NOT maintenance_private.quote_partner_matches(c,partner_id,selected);
INSERT INTO public.maintenance_driver_report_dispatches(company_id,report_id,partner_id) SELECT c,r.id,p.id FROM public.maintenance_partners p WHERE p.company_id=c AND maintenance_private.quote_partner_matches(c,p.id,selected) ON CONFLICT(report_id,partner_id) DO UPDATE SET status='pending',error_message=NULL WHERE public.maintenance_driver_report_dispatches.status IN ('obsolete','failed','unavailable');
GET DIAGNOSTICS amount=ROW_COUNT;
INSERT INTO public.maintenance_driver_report_events(company_id,report_id,actor_id,action,message) VALUES(c,r.id,auth.uid(),'encaminhamento','Envio preparado com tipos selecionados: '||array_to_string(selected,', '));RETURN jsonb_build_object('prepared',amount,'id',r.id);END IF;
IF action='dispatch_list' THEN RETURN jsonb_build_object('rows',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'status',status)) FROM public.maintenance_driver_report_dispatches WHERE report_id=r.id AND company_id=c),'[]'::jsonb));END IF;
SELECT * INTO dispatch FROM public.maintenance_driver_report_dispatches WHERE id=(b->>'dispatch_id')::uuid AND report_id=r.id AND company_id=c FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Envio não encontrado.';END IF;
IF action='dispatch_claim' THEN
IF dispatch.status='sending' AND dispatch.started_at<clock_timestamp()-interval '2 minutes' THEN UPDATE public.maintenance_driver_report_dispatches SET status='unknown' WHERE id=dispatch.id;dispatch.status:='unknown';END IF;
IF dispatch.status='accepted' OR dispatch.status='sending' OR (dispatch.status='unknown' AND NOT coalesce((b->>'confirm_uncertain')::boolean,false)) THEN RETURN jsonb_build_object('status',dispatch.status);END IF;
IF r.status IN ('resolvida','cancelada') OR NOT maintenance_private.quote_partner_matches(c,dispatch.partner_id,r.partner_types) THEN IF dispatch.status NOT IN ('unknown','sending') THEN UPDATE public.maintenance_driver_report_dispatches SET status='obsolete' WHERE id=dispatch.id;END IF;RETURN jsonb_build_object('status','obsolete','error','Oficina fora dos filtros ou solicitação encerrada.');END IF;
SELECT * INTO recipient FROM public.maintenance_partners WHERE id=dispatch.partner_id AND company_id=c FOR SHARE;phone:=driver_portal_private.phone(coalesce(nullif(recipient.whatsapp,''),recipient.telefone));
IF phone IS NULL THEN UPDATE public.maintenance_driver_report_dispatches SET status='unavailable',error_message='Contato inválido.' WHERE id=dispatch.id;RETURN jsonb_build_object('status','unavailable');END IF;
UPDATE public.maintenance_driver_report_dispatches SET status='sending',claim_token=gen_random_uuid(),started_at=clock_timestamp(),attempts=attempts+1,updated_at=clock_timestamp(),error_message=NULL WHERE id=dispatch.id RETURNING * INTO dispatch;
RETURN jsonb_build_object('status','claimed','token',dispatch.claim_token,'phone',phone,'snapshot',jsonb_build_object('report',driver_portal_private.report_public(r),'vehicle',r.vehicle_snapshot,'company',(SELECT nome FROM public.companies WHERE id=c),'partner',coalesce(recipient.nome_fantasia,recipient.razao_social)));END IF;
IF action='dispatch_finish' THEN
IF dispatch.claim_token IS DISTINCT FROM (b->>'token')::uuid OR dispatch.status<>'sending' THEN RETURN jsonb_build_object('status',dispatch.status);END IF;
IF b->>'status' NOT IN ('accepted','failed','unknown') OR b->>'status' IS NULL THEN RAISE EXCEPTION 'Resultado inválido.';END IF;
UPDATE public.maintenance_driver_report_dispatches SET status=b->>'status',message_id=left(b->>'message_id',200),updated_at=clock_timestamp(),error_message=CASE b->>'status' WHEN 'failed' THEN 'Falha no envio. Verifique a instância e tente novamente.' WHEN 'unknown' THEN 'Resultado incerto. Confira o WhatsApp antes de repetir.' ELSE NULL END WHERE id=dispatch.id;
INSERT INTO public.maintenance_driver_report_events(company_id,report_id,actor_id,action,message) VALUES(c,r.id,auth.uid(),'envio_oficina','Envio à oficina '||(SELECT coalesce(nome_fantasia,razao_social) FROM public.maintenance_partners WHERE id=dispatch.partner_id)||': '||(b->>'status'));RETURN jsonb_build_object('status',b->>'status');END IF;
RAISE EXCEPTION 'Ação inválida.';
END $$;
REVOKE ALL ON FUNCTION driver_portal_private.admin_command(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION driver_portal_private.admin_command(uuid,text,jsonb) TO authenticated;
CREATE FUNCTION public.driver_maintenance_admin(target_company uuid,command text,body jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT driver_portal_private.admin_command(target_company,command,body);$$;
REVOKE ALL ON FUNCTION public.driver_maintenance_admin(uuid,text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.driver_maintenance_admin(uuid,text,jsonb) TO authenticated;
COMMIT;